      "state": {
        "operation": "u + v",
        "construction": "attach v (or -v) head-to-tail"
      }
    },
    {
      "title": "Close the parallelogram",
      "narration": "Copies of u and v complete the figure, showing that the head-to-tail path and the parallelogram give the same endpoint.",
      "state": {
        "operation": "u + v",
