    A: { x: O.x + U.x, y: O.y + U.y },
    B: { x: O.x + U.x + V.x, y: O.y + U.y + V.y },
    C: { x: O.x + V.x, y: O.y + V.y }
  };
}

var CONSTR_NAMES = ['draw u', 'attach v (or \u2212v) head-to-tail', 'complete parallelogram', 'reveal resultant diagonal'];
var HLSETS = {
  sum: ['left-u', 'left-v', 'left-sum'],
  diff: ['right-utop', 'right-negv', 'right-diff']
};

var op = 'both';      // 'add' | 'sub' | 'both'
var constr = 3;       // 0..3
var selected = null;  // null | 'sum' | 'diff'

/* ---------- colour resolution ---------- */
function isHL(role) { return selected && HLSETS[selected].indexOf(role) >= 0; }
function strokeCol(role, base) { if (!selected) return base; return isHL(role) ? AMBER : FADE; }
function vecCol(role) { if (!selected) return ORANGE; return isHL(role) ? AMBER : FADE; }
function textCol(role) { if (!selected) return '#141414'; return isHL(role) ? '#a06000' : '#c2c7cd'; }

/* ---------- drawing primitives ---------- */
function figLerp(p, q, t) { return { x: p.x + (q.x - p.x) * t, y: p.y + (q.y - p.y) * t }; }

function figEdge(g, p, q, role) {
  return g.line(p.x, p.y, q.x, q.y)
    .stroke({ color: strokeCol(role, NAVY), width: isHL(role) ? 5.2 : 3.4, linecap: 'round' });
}

function figThin(g, p, q, role) {
  return g.line(p.x, p.y, q.x, q.y)
    .stroke({ color: strokeCol(role, NAVY), width: isHL(role) ? 3.2 : 1.1, linecap: 'round' });
}

function figGlow(g, p, q) {
  g.line(p.x, p.y, q.x, q.y).stroke({ color: AMBER, width: 12, opacity: 0.22, linecap: 'round' });
}

function figVec(g, p0, p1, opts) {
  opts = opts || {};
  var color = opts.color || ORANGE, w = opts.width || 4.2, frac = (opts.frac == null) ? 0 : opts.frac;
  var dx = p1.x - p0.x, dy = p1.y - p0.y, L = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / L, uy = dy / L, px = -uy, py = ux;
  var off = opts.offset || 0;
  var s = figLerp(p0, p1, frac);
  var hl = opts.headLen || 12, hw = opts.headW || 9;
  var sx = s.x + px * off, sy = s.y + py * off, ex = p1.x + px * off, ey = p1.y + py * off;
  var bx = ex - ux * hl, by = ey - uy * hl;
  var grp = g.group();
  var ln = grp.line(sx, sy, bx, by).stroke({ color: color, width: w, linecap: 'butt' });
  if (opts.dashed) ln.attr('stroke-dasharray', '6,4');
  grp.polygon([[ex, ey], [bx + px * hw / 2, by + py * hw / 2], [bx - px * hw / 2, by - py * hw / 2]]).fill(color);
  if (opts.opacity != null) grp.opacity(opts.opacity);
  if (opts.tip) {
    grp.css('cursor', 'pointer');
    grp.on('mousemove', function (e) { showTooltip(opts.tip, e); });
    grp.on('mouseleave', hideTooltip);
    if (opts.popTitle) grp.on('click', function (e) { e.stopPropagation(); showPopup(opts.popTitle, opts.popBody); });
  }
  return grp;
}

function figDot(g, p) {
  g.circle(5.8).center(p.x, p.y).fill(selected ? FADE : NAVY);
}

function figLab(g, txt, x, y, anchor, role) {
  var t = g.text(txt);
  t.font({ family: 'Georgia, "Times New Roman", serif', size: 15, style: 'italic', weight: 'bold', anchor: anchor || 'middle' });
  t.fill(textCol(role));
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4.5, 'stroke-linejoin': 'round' });
  t.attr('x', x); t.attr('y', y);
  try {
    t.children().forEach(function (c) { c.attr('x', x); c.attr('dy', 0); });
  } catch (e) { }
  return t;
}

function figHit(g, p, q, which, title, body, tip) {
  var h = g.line(p.x, p.y, q.x, q.y).stroke({ color: '#000', width: 18, opacity: 0 }).css('cursor', 'pointer');
  h.on('mousemove', function (e) { showTooltip(tip, e); });
  h.on('mouseleave', hideTooltip);
  h.on('click', function (e) {
    e.stopPropagation();
    hideTooltip();
    if (selected === which) { selected = null; render(); hidePopup(); }
    else { selected = which; render(); showPopup(title, body); }
  });
  return h;
}

/* ---------- panels ---------- */
function drawAdd(g, stage, active) {
  var P = figVerts(LO);
  var full = stage >= 2;

  if (full) { figEdge(g, P.O, P.C, 'left-other'); figEdge(g, P.C, P.B, 'left-other'); }
  figEdge(g, P.O, P.A, 'left-u');
  if (stage >= 1) figEdge(g, P.A, P.B, 'left-v');
  if (full) figThin(g, P.C, P.A, 'left-other');
  if (stage >= 3) {
    if (selected === 'sum') figGlow(g, P.O, P.B);
    figThin(g, P.O, P.B, 'left-sum');
  }

  figVec(g, P.O, P.A, {
    color: vecCol('left-u'), frac: 0.6,
    tip: 'u  \u2014 drawn from the common tail',
    popTitle: 'The vector u',
    popBody: 'u starts at the shared tail (lower-left corner) and runs along the bottom edge. Every other piece of the figure is built from this starting arrow.'
  });
  if (stage >= 1) figVec(g, P.A, P.B, {
    color: vecCol('left-v'), frac: 0.5,
    tip: 'v  \u2014 tail placed at the head of u',
    popTitle: 'The vector v, head-to-tail',
    popBody: 'v is translated so its tail sits at the head of u. Its free end is already the answer to u + v; the parallelogram is just the record of that translation.'
  });
  if (stage >= 3) {
    figVec(g, P.O, P.B, { color: vecCol('left-sum'), frac: 0.62 });
    if (active) figHit(g, P.O, P.B, 'sum',
      'u + v : the long diagonal',
      'Starting at the common tail and walking u then v lands on the opposite corner. So the diagonal drawn from the shared tail of u and v is exactly u + v. The two highlighted edges are the vectors that generate it.',
      'Click: u + v = diagonal from the common tail');
  }

  figDot(g, P.O); figDot(g, P.A);
  if (stage >= 1) figDot(g, P.B);
  if (full) figDot(g, P.C);

  figLab(g, 'u', 115, 211, 'middle', 'left-u');
  if (stage >= 1) figLab(g, 'v', 238, 143, 'start', 'left-v');
  if (stage >= 3) figLab(g, 'u + v', 112, 119, 'middle', 'left-sum');
}

function drawSub(g, stage, active) {
  var P = figVerts(RO);

  figEdge(g, P.O, P.A, 'right-ubot');
  if (stage >= 1) {
    figEdge(g, P.O, P.C, 'right-other');
    figEdge(g, P.C, P.B, 'right-utop');
    figEdge(g, P.B, P.A, 'right-negv');
  }
  if (stage >= 2) figThin(g, P.O, P.B, 'right-other');
  if (stage >= 3) {
    if (selected === 'diff') figGlow(g, P.C, P.A);
    figThin(g, P.C, P.A, 'right-diff');
  }

  if (stage === 0) {
    figVec(g, P.O, P.A, {
      color: vecCol('right-ubot'), frac: 0.6,
      tip: 'u  \u2014 from the common tail',
      popTitle: 'The vector u', popBody: 'Subtraction starts from exactly the same u.'
    });
  }
  if (stage >= 1) {
    if (op === 'sub') figVec(g, P.A, P.B, {
      color: GHOST, frac: 0, dashed: true, width: 2.2, opacity: 0.85, offset: 8,
      tip: 'the original v (about to be reversed)'
    });
    figVec(g, P.C, P.B, {
      color: vecCol('right-utop'), frac: 0.6,
      tip: 'u  \u2014 translated copy, tail at the head of v',
      popTitle: 'u moved to the top edge',
      popBody: 'This is the same vector u, translated so its tail sits at the head of v. From there we attach \u2212v head-to-tail.'
    });
    figVec(g, P.B, P.A, {
      color: vecCol('right-negv'), frac: 0.4,
      tip: '\u2212v  \u2014 v reversed, pointing down-right',
      popTitle: 'Reversing v gives \u2212v',
      popBody: 'Subtracting v is the same as adding the reversed arrow \u2212v. It has the same length and slant as v but points the opposite way (dashed grey shows the original v).'
    });
  }
  if (stage >= 3) {
    figVec(g, P.C, P.A, { color: vecCol('right-diff'), frac: 0.62 });
    if (active) figHit(g, P.C, P.A, 'diff',
      'u \u2212 v : the diagonal joining the two heads',
      'Walking u then \u2212v from the head of v lands on the head of u. So u \u2212 v is the second diagonal of the very same parallelogram \u2014 the one that joins the two arrow heads, pointing from the head of v toward the head of u.',
      'Click: u \u2212 v = diagonal joining the two heads');
  }

  figDot(g, P.O); figDot(g, P.A);
  if (stage >= 1) { figDot(g, P.B); figDot(g, P.C); }

  figLab(g, 'u', 430, 211, 'middle', 'right-ubot');
  if (stage >= 1) {
    figLab(g, 'u', 482, 67, 'middle', 'right-utop');
    figLab(g, '\u2212v', 548, 143, 'start', 'right-negv');
  }
  if (stage >= 3) figLab(g, 'u \u2212 v', 455, 126, 'middle', 'right-diff');
}

/* ---------- master render ---------- */
function render() {
  figDraw.clear();
  var bg = figDraw.rect(FW, FH).fill('#ffffff');
  bg.on('click', function () { if (selected) { selected = null; render(); hidePopup(); } });

  var leftActive = (op !== 'sub'), rightActive = (op !== 'add');
  var gL = figDraw.group(), gR = figDraw.group();
  drawAdd(gL, leftActive ? constr : 3, leftActive);
  drawSub(gR, rightActive ? constr : 3, rightActive);
  if (!leftActive) gL.opacity(0.13);
  if (!rightActive) gR.opacity(0.13);

  window.__markRendered();
}

/* ---------- controls ---------- */
function toggle_operation(v) {
  op = v; selected = null; render();
}

function trigger_construction() {
  constr = (constr + 1) % 4;
  selected = null;
  updateConstrLabel();
  render();
}

function updateConstrLabel() {
  var o = document.getElementById('constructionVal');
  if (o) o.value = CONSTR_NAMES[constr];
}

function clearHighlight() {
  selected = null; hidePopup(); render();
}

function showKeyInsight() {
  showPopup('Key insight',
    'One parallelogram holds both answers: its long diagonal from the common tail is u + v, and the diagonal joining the two heads is u \u2212 v \u2014 because u \u2212 v is just u + (\u2212v).');
}

/* ---------- demo steps ---------- */
var STEPS = [
  {
    t: 'The textbook figure',
    n: 'The same parallelogram drawn twice. Left: u along the bottom and v up the right side, with the diagonal u + v. Right: u translated to the top edge and v reversed into \u2212v, giving the other diagonal u \u2212 v. Press \u25b6 to build it step by step.',
    op: 'both', c: 3
  },
  {
    t: 'Start with u alone',
    n: 'Only the vector u is drawn from the common tail, pointing right along the bottom edge. Everything else in the parallelogram will be built from here.',
    op: 'add', c: 0
  },
  {
    t: 'Attach v head-to-tail',
    n: 'v is placed with its tail at the head of u, slanting up and to the right. The free end of v is already the answer to u + v.',
    op: 'add', c: 1
  },
  {
    t: 'Close the parallelogram',
    n: 'Copies of u and v complete the figure, showing that the head-to-tail path and the parallelogram give the same endpoint.',
    op: 'add', c: 2
  },
  {
    t: 'Reveal u + v',
    n: 'The diagonal from the shared tail to the opposite corner is u + v \u2014 the long diagonal of the parallelogram.',
    op: 'add', c: 3
  },
  {
    t: 'Flip v into \u2212v',
    n: 'Switching to subtraction reverses v: the orange arrow on the slanted edge now points down and to the right, with the original v ghosted behind it.',
    op: 'sub', c: 1
  },
  {
    t: 'Reveal u \u2212 v',
    n: 'Adding \u2212v head-to-tail to u lands on the other corner, so u \u2212 v is the second diagonal, running from the head of v down to the head of u.',
    op: 'sub', c: 3
  },
  {
    t: 'Both diagonals at once',
    n: 'Displayed together, the sum and the difference are simply the two diagonals of one parallelogram. Click either diagonal to highlight the pair of edges that produce it.',
    op: 'both', c: 3
  }
];
var step = 0;

function applyStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  var s = STEPS[step];
  op = s.op; constr = s.c; selected = null;
  var sel = document.getElementById('operationInput');
  if (sel) sel.value = op;
  updateConstrLabel();
  var nar = document.getElementById('demoNarration');
  if (nar) nar.textContent = s.t + ' \u2014 ' + s.n;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (step === 0) ? 'Overview' : ('Step ' + step + ' of 7');
  hidePopup();
  render();
}
function nextStep() { applyStep(step + 1); }
function prevStep() { applyStep(step - 1); }

applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The sum u + v and the difference u - v are the two diagonals of the same parallelogram, because subtracting v is the same as adding the reversed vector -v head-to-tail with u.
KEY INSIGHT (what students should walk away understanding): One parallelogram holds both answers: its long diagonal from the common tail is u + v, and the diagonal joining the two heads is u - v, because u - v is just u + (-v).
DEMO STEPS: 7 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The sum u + v and the difference u - v are the two diagonals of the same parallelogram, because subtracting v is the same as adding the reversed vector -v head-to-tail with u.",
  "figureType": "diagram",
  "elements": [
    "Left parallelogram: dark navy outline, lower-left vertex as common origin, bottom edge horizontal, right edge slanting up-right",
    "Left parallelogram both diagonals drawn as thin navy lines (lower-left to upper-right, and upper-left to lower-right)",
    "Left: bottom edge with orange arrowhead pointing right, italic label u below it",
    "Left: right slanted edge with orange arrowhead pointing up-and-right, italic label v to its right",
    "Left: main diagonal from lower-left to upper-right ending in orange arrowhead, italic label u + v placed above the diagonal near its midpoint",
    "Right parallelogram: identical navy outline and thin diagonals, placed beside the left one",
    "Right: top edge with orange arrowhead pointing right, italic label u above it",
    "Right: bottom edge also labeled italic u (no arrowhead emphasis or a faint one) to show the translated copy",
    "Right: slanted right edge with orange arrowhead pointing down-and-right, italic label -v to its right",
    "Right: diagonal descending from upper-left vertex toward lower-right vertex, labeled italic u - v near its midpoint",
    "Vertex dots at the four corners of each parallelogram",
    "Optional legend/caption strip: 'addition = long diagonal from the common tail' vs 'subtraction = diagonal joining the two heads'",
    "Ghosted (dashed grey) copy of v shown when -v is displayed, to mark the reversal"
  ],
  "interactions": [
    {
      "id": "operation",
      "type": "toggle",
      "teaches": "Subtraction is not a new operation: flipping v to -v turns the same parallelogram's other diagonal into the answer.",
      "label": "Operation",
      "options": [
        "u + v",
        "u - v",
        "Show both"
      ],
      "default": "u + v"
    },
    {
      "id": "construction",
      "type": "button",
      "teaches": "The resultant is the endpoint of a deliberate head-to-tail construction, not an arbitrary line inside the shape.",
      "label": "Construction step",
      "states": [
        "draw u",
        "attach v (or -v) head-to-tail",
        "complete parallelogram",
        "reveal resultant diagonal"
      ],
      "default": "draw u"
    },
    {
      "id": "selectDiagonal",
      "type": "click",
      "teaches": "Each diagonal belongs to a specific pair of side vectors — clicking one lights up exactly the two edges that generate it.",
      "teaches_note": "click a diagonal to highlight it and its two component edges"
    }
  ],
  "demo_steps": [
    {
      "title": "Start with u alone",
      "narration": "Only the vector u is drawn from the common tail, pointing right along the bottom edge. Everything else in the parallelogram will be built from here.",
      "state": {
        "operation": "u + v",
        "construction": "draw u"
      }
    },
    {
      "title": "Attach v head-to-tail",
      "narration": "v is placed with its tail at the head of u, slanting up and to the right. The free end of v is already the answer to u + v.",
      "state": {
        "operation": "u + v",
        "construction": "attach v (or -v) head-to-tail"
      }
    },
    {
      "title": "Close the parallelogram",
      "narration": "Copies of u and v complete the figure, showing that the head-to-tail path and the parallelogram give the same endpoint.",
      "state": {
        "operation": "u + v",
        "construction": "complete parallelogram"
      }
    },
    {
      "title": "Reveal u + v",
      "narration": "The diagonal from the shared tail to the opposite corner is u + v — the long diagonal of the parallelogram.",
      "state": {
        "operation": "u + v",
        "construction": "reveal resultant diagonal"
      }
    },
    {
      "title": "Flip v into -v",
      "narration": "Switching to subtraction reverses v: the orange arrow on the slanted edge now points down and to the right, with the original v ghosted behind it.",
      "state": {
        "operation": "u - v",
        "construction": "attach v (or -v) head-to-tail"
      }
    },
    {
      "title": "Reveal u - v",
      "narration": "Adding -v head-to-tail to u lands on the other corner, so u - v is the second diagonal, running from the head of v down to the head of u.",
      "state": {
        "operation": "u - v",
        "construction": "reveal resultant diagonal"
      }
    },
    {
      "title": "Both diagonals at once",
      "narration": "Displayed together, the sum and the difference are simply the two diagonals of one parallelogram. Click either diagonal to highlight the pair of edges that produce it.",
      "state": {
        "operation": "Show both",
        "construction": "reveal resultant diagonal"
      }
    }
  ],
  "keyInsight": "One parallelogram holds both answers: its long diagonal from the common tail is u + v, and the diagonal joining the two heads is u - v, because u - v is just u + (-v).",
  "reconstructionNotes": "Two congruent slanted parallelograms side by side on white, each outlined in thick dark navy (#1F4E79) with thin navy diagonals inside. Bottom edges horizontal; right edges slant up-right at roughly 60°. Active vectors are drawn as bold orange (#E8622A) segments with solid arrowheads laid on top of the navy edges; inactive edges stay plain navy. Left figure: orange arrow right along the bottom edge labeled italic u, orange arrow up-right along the right edge labeled italic v, and an orange-tipped diagonal from the lower-left vertex to the upper-right vertex labeled italic u + v just above its midpoint. Right figure: orange arrow right along the top edge labeled italic u above it, the bottom edge also labeled italic u, an orange arrow pointing down-right on the right edge labeled italic -v, and the descending diagonal from the upper-left vertex toward the lower-right vertex labeled italic u - v near its midpoint. When -v is shown, render the original v as a dashed grey arrow to mark the reversal. Labels in serif italic, matching textbook style. Highlight state: selected diagonal thickens and turns amber with a soft glow, its two component edges also turn amber, all other strokes fade to light grey."
}

